From 344b27d71e08eb740681a982fc816333a2d165e6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:58:22 +0100
Subject: [PATCH] applets/taskmanager: support overlay icons from the Unity
 launcher API

Apps could only show a count badge or progress on their task icons, so
there was no way to tell e.g. two browser profiles apart. Read the new
"overlay-icon" key (icon name or local file) and show it as an emblem.

BUG: 472737
---
 applets/taskmanager/qml/Task.qml             | 12 ++++++++++
 applets/taskmanager/smartlauncherbackend.cpp | 23 ++++++++++++++++++++
 applets/taskmanager/smartlauncherbackend.h   |  3 +++
 applets/taskmanager/smartlauncheritem.cpp    | 21 ++++++++++++++++++
 applets/taskmanager/smartlauncheritem.h      |  5 +++++
 5 files changed, 64 insertions(+)

diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..e85fffdcbe 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -580,6 +580,18 @@ PlasmaCore.ToolTipArea {
             source: task.model.decoration
         }

+        Kirigami.Icon {
+            // Stay clear of the badge when it moves to the bottom
+            x: iconBox.item?.shiftBadgeDown ? 0 : parent.width - width
+            anchors.bottom: parent.bottom
+            width: Math.round(Math.min(parent.width, parent.height) / 2)
+            height: width
+            z: 1
+
+            visible: source !== ""
+            source: task.smartLauncherItem?.overlayIcon ?? ""
+        }
+
         states: [
             // Using a state transition avoids a binding loop between label.visible and
             // the text label margin, which derives from the icon width.
diff --git a/applets/taskmanager/smartlauncherbackend.cpp b/applets/taskmanager/smartlauncherbackend.cpp
index 803b447ede..b80667da99 100644
--- a/applets/taskmanager/smartlauncherbackend.cpp
+++ b/applets/taskmanager/smartlauncherbackend.cpp
@@ -10,6 +10,8 @@
 #include <QDBusMessage>
 #include <QDBusServiceWatcher>
 #include <QDebug>
+#include <QDir>
+#include <QUrl>

 #include <KConfigGroup>
 #include <KService>
@@ -138,6 +140,11 @@ bool Backend::urgent(const QString &uri) const
     return m_launchers.value(uri).urgent;
 }

+QString Backend::overlayIcon(const QString &uri) const
+{
+    return m_launchers.value(uri).overlayIcon;
+}
+
 QHash<QString, QString> Backend::unityMappingRules() const
 {
     return m_unityMappingRules;
@@ -230,6 +237,22 @@ void Backend::update(const QString &uri, const QMap<QString, QVariant> &properti
                            &Backend::progressVisible,
                            &Backend::progressVisibleChanged);
     updateLauncherProperty(storageId, properties, QStringLiteral("urgent"), &foundEntry->urgent, &Backend::urgent, &Backend::urgentChanged);
+
+    // An icon name or a local file, like the overlay icon of a StatusNotifierItem
+    auto foundOverlayIcon = properties.constFind(QStringLiteral("overlay-icon"));
+    if (foundOverlayIcon != propertiesEnd) {
+        QString overlayIcon = foundOverlayIcon->toString();
+        if (QDir::isAbsolutePath(overlayIcon)) {
+            overlayIcon = QUrl::fromLocalFile(overlayIcon).toString();
+        } else if (overlayIcon.contains(QLatin1Char(':')) && !QUrl(overlayIcon).isLocalFile()) {
+            overlayIcon.clear();
+        }
+
+        if (overlayIcon != foundEntry->overlayIcon) {
+            foundEntry->overlayIcon = overlayIcon;
+            Q_EMIT overlayIconChanged(storageId, overlayIcon);
+        }
+    }
 }

 void Backend::onServiceUnregistered(const QString &service)
diff --git a/applets/taskmanager/smartlauncherbackend.h b/applets/taskmanager/smartlauncherbackend.h
index 5354efb85f..c0bce24d87 100644
--- a/applets/taskmanager/smartlauncherbackend.h
+++ b/applets/taskmanager/smartlauncherbackend.h
@@ -29,6 +29,7 @@ struct Entry {
     int progress = 0;
     bool progressVisible = false;
     bool urgent = false;
+    QString overlayIcon;
 };

 class Backend : public QObject, protected QDBusContext
@@ -46,6 +47,7 @@ public:
     int progress(const QString &uri) const;
     bool progressVisible(const QString &uri) const;
     bool urgent(const QString &uri) const;
+    QString overlayIcon(const QString &uri) const;

     QHash<QString, QString> unityMappingRules() const;

@@ -55,6 +57,7 @@ Q_SIGNALS:
     void progressChanged(const QString &uri, int progress);
     void progressVisibleChanged(const QString &uri, bool progressVisible);
     void urgentChanged(const QString &uri, bool urgent);
+    void overlayIconChanged(const QString &uri, const QString &overlayIcon);

     void reloadRequested(const QString &uri);
     void launcherRemoved(const QString &uri);
diff --git a/applets/taskmanager/smartlauncheritem.cpp b/applets/taskmanager/smartlauncheritem.cpp
index 2eadd2fa93..67a7f14377 100644
--- a/applets/taskmanager/smartlauncheritem.cpp
+++ b/applets/taskmanager/smartlauncheritem.cpp
@@ -74,6 +74,12 @@ void Item::init()
         }
     });

+    connect(m_backendPtr.get(), &Backend::overlayIconChanged, this, [this](const QString &uri, const QString &overlayIcon) {
+        if (uri.isEmpty() || m_storageId == uri) {
+            setOverlayIcon(overlayIcon);
+        }
+    });
+
     m_inited = true;
 }

@@ -92,6 +98,7 @@ void Item::populate()
     setProgress(m_backendPtr->progress(m_storageId));
     setProgressVisible(m_backendPtr->progressVisible(m_storageId));
     setUrgent(m_backendPtr->urgent(m_storageId));
+    setOverlayIcon(m_backendPtr->overlayIcon(m_storageId));
 }

 void Item::clear()
@@ -101,6 +108,7 @@ void Item::clear()
     setProgress(0);
     setProgressVisible(false);
     setUrgent(false);
+    setOverlayIcon(QString());
 }

 QUrl Item::launcherUrl() const
@@ -222,4 +230,17 @@ void Item::setUrgent(bool urgent)
     }
 }

+QString Item::overlayIcon() const
+{
+    return m_overlayIcon;
+}
+
+void Item::setOverlayIcon(const QString &overlayIcon)
+{
+    if (m_overlayIcon != overlayIcon) {
+        m_overlayIcon = overlayIcon;
+        Q_EMIT overlayIconChanged(overlayIcon);
+    }
+}
+
 #include "moc_smartlauncheritem.cpp"
diff --git a/applets/taskmanager/smartlauncheritem.h b/applets/taskmanager/smartlauncheritem.h
index eb06b43aaa..a2bd7e2490 100644
--- a/applets/taskmanager/smartlauncheritem.h
+++ b/applets/taskmanager/smartlauncheritem.h
@@ -28,6 +28,7 @@ class Item : public QObject
     Q_PROPERTY(int progress READ progress NOTIFY progressChanged)
     Q_PROPERTY(bool progressVisible READ progressVisible NOTIFY progressVisibleChanged)
     Q_PROPERTY(bool urgent READ urgent NOTIFY urgentChanged)
+    Q_PROPERTY(QString overlayIcon READ overlayIcon NOTIFY overlayIconChanged)

 public:
     explicit Item(QObject *parent = nullptr);
@@ -41,6 +42,7 @@ public:
     int progress() const;
     bool progressVisible() const;
     bool urgent() const;
+    QString overlayIcon() const;

 Q_SIGNALS:
     void launcherUrlChanged(const QUrl &launcherUrl);
@@ -50,6 +52,7 @@ Q_SIGNALS:
     void progressChanged(int progress);
     void progressVisibleChanged(bool progressVisible);
     void urgentChanged(bool urgent);
+    void overlayIconChanged(const QString &overlayIcon);

 private:
     void init();
@@ -62,6 +65,7 @@ private:
     void setProgress(int progress);
     void setProgressVisible(bool progressVisible);
     void setUrgent(bool urgent);
+    void setOverlayIcon(const QString &overlayIcon);

     static std::weak_ptr<Backend> s_backend;

@@ -77,6 +81,7 @@ private:
     int m_progress = 0;
     bool m_progressVisible = false;
     bool m_urgent = false;
+    QString m_overlayIcon;
 };

 } // namespace SmartLauncher
